import type { ClimbQueueItem } from '../types';

// MARK: - JS reducer

export type LegacyQueueState = {
  queue: ClimbQueueItem[];
  currentClimbQueueItem: ClimbQueueItem | null;
  pendingCurrentClimbUpdates: string[];
};

export type LegacyQueueAction =
  | {
      type: 'INITIAL_QUEUE_DATA';
      payload: { queue: ClimbQueueItem[]; currentClimbQueueItem?: ClimbQueueItem | null };
    }
  | { type: 'DELTA_ADD_QUEUE_ITEM'; payload: { item: ClimbQueueItem; position?: number } }
  | { type: 'DELTA_REMOVE_QUEUE_ITEM'; payload: { uuid: string } }
  | { type: 'DELTA_REORDER_QUEUE_ITEM'; payload: { uuid: string; oldIndex: number; newIndex: number } }
  | {
      type: 'DELTA_UPDATE_CURRENT_CLIMB';
      payload: {
        item: ClimbQueueItem | null;
        shouldAddToQueue?: boolean;
        insertAfterCurrent?: boolean;
        isServerEvent?: boolean;
        eventClientId?: string;
        myClientId?: string;
        correlationId?: string;
        serverCorrelationId?: string;
      };
    }
  | { type: 'DELTA_MIRROR_CURRENT_CLIMB'; payload: { mirrored: boolean; mirroredUuid: string | null } };

export function legacyInsertQueueItemIdempotent<TItem extends { uuid: string }>(
  queue: TItem[],
  item: TItem,
  position?: number,
): TItem[] {
  if (queue.some((existingItem) => existingItem.uuid === item.uuid)) {
    return queue;
  }

  const nextQueue = [...queue];
  if (position !== undefined && position >= 0 && position <= nextQueue.length) {
    nextQueue.splice(position, 0, item);
    return nextQueue;
  }

  nextQueue.push(item);
  return nextQueue;
}

export type LegacySequenceDecision = 'apply' | 'ignore-stale' | 'gap';

export function legacyEvaluateQueueEventSequence(
  lastSequence: number | null,
  eventSequence: number,
): LegacySequenceDecision {
  if (lastSequence === null) return 'apply';
  if (eventSequence <= lastSequence) return 'ignore-stale';
  if (eventSequence > lastSequence + 1) return 'gap';
  return 'apply';
}

function hasCurrentClimbQueueItem(payload: { currentClimbQueueItem?: ClimbQueueItem | null }): boolean {
  return Object.prototype.hasOwnProperty.call(payload, 'currentClimbQueueItem');
}

export function legacyQueueReducer(state: LegacyQueueState, action: LegacyQueueAction): LegacyQueueState {
  switch (action.type) {
    case 'INITIAL_QUEUE_DATA': {
      const filteredQueue = action.payload.queue.filter(
        (item): item is NonNullable<typeof item> => item != null && item.climb != null,
      );
      return {
        ...state,
        queue: filteredQueue,
        currentClimbQueueItem: hasCurrentClimbQueueItem(action.payload)
          ? (action.payload.currentClimbQueueItem ?? null)
          : state.currentClimbQueueItem,
        pendingCurrentClimbUpdates: [],
      };
    }

    case 'DELTA_ADD_QUEUE_ITEM': {
      const { item, position } = action.payload;
      if (!item || !item.climb) return state;
      const newQueue = legacyInsertQueueItemIdempotent(state.queue, item, position);
      if (newQueue === state.queue) return state;
      return { ...state, queue: newQueue };
    }

    case 'DELTA_REMOVE_QUEUE_ITEM': {
      const { uuid } = action.payload;
      return {
        ...state,
        queue: state.queue.filter((item) => item.uuid !== uuid),
        currentClimbQueueItem: state.currentClimbQueueItem?.uuid === uuid ? null : state.currentClimbQueueItem,
      };
    }

    case 'DELTA_REORDER_QUEUE_ITEM': {
      const { uuid, oldIndex, newIndex } = action.payload;
      const newQueue = [...state.queue];
      if (oldIndex < 0 || oldIndex >= newQueue.length || newIndex < 0 || newIndex >= newQueue.length) {
        return state;
      }
      if (newQueue[oldIndex].uuid !== uuid) return state;
      const [movedItem] = newQueue.splice(oldIndex, 1);
      newQueue.splice(newIndex, 0, movedItem);
      return { ...state, queue: newQueue };
    }

    case 'DELTA_UPDATE_CURRENT_CLIMB': {
      const {
        item,
        shouldAddToQueue,
        insertAfterCurrent,
        isServerEvent,
        eventClientId,
        myClientId,
        correlationId,
        serverCorrelationId,
      } = action.payload;

      let pendingUpdates = state.pendingCurrentClimbUpdates;

      if (isServerEvent && item) {
        if (serverCorrelationId && pendingUpdates.includes(serverCorrelationId)) {
          return {
            ...state,
            pendingCurrentClimbUpdates: pendingUpdates.filter((id) => id !== serverCorrelationId),
          };
        }
        const isOurOwnEcho = eventClientId && myClientId && eventClientId === myClientId;
        if (isOurOwnEcho) {
          return { ...state, pendingCurrentClimbUpdates: pendingUpdates };
        }
      }

      if (!isServerEvent && item && state.currentClimbQueueItem?.uuid === item.uuid) {
        if (!correlationId) return state;
        return {
          ...state,
          pendingCurrentClimbUpdates: [...state.pendingCurrentClimbUpdates, correlationId].slice(-50),
        };
      }

      let newQueue = state.queue;
      if (item && item.climb && shouldAddToQueue && !state.queue.find((qItem) => qItem?.uuid === item.uuid)) {
        if (insertAfterCurrent && state.currentClimbQueueItem) {
          const currentIndex = state.queue.findIndex((q) => q.uuid === state.currentClimbQueueItem?.uuid);
          if (currentIndex >= 0) {
            newQueue = [...state.queue.slice(0, currentIndex + 1), item, ...state.queue.slice(currentIndex + 1)];
          } else {
            newQueue = [...state.queue, item];
          }
        } else {
          newQueue = [...state.queue, item];
        }
      }

      if (!isServerEvent && item && correlationId) {
        pendingUpdates = [...pendingUpdates, correlationId].slice(-50);
      }

      return {
        ...state,
        queue: newQueue,
        currentClimbQueueItem: item,
        pendingCurrentClimbUpdates: pendingUpdates,
      };
    }

    case 'DELTA_MIRROR_CURRENT_CLIMB': {
      const { mirrored, mirroredUuid } = action.payload;
      if (mirroredUuid === null) return state;
      const mirrorsCurrent = state.currentClimbQueueItem?.uuid === mirroredUuid;
      if (!mirrorsCurrent && !state.queue.some((item) => item.uuid === mirroredUuid)) return state;
      const mirrorItem = (item: ClimbQueueItem) => ({ ...item, climb: { ...item.climb, mirrored } });
      return {
        ...state,
        queue: state.queue.map((item) => (item.uuid === mirroredUuid ? mirrorItem(item) : item)),
        currentClimbQueueItem:
          mirrorsCurrent && state.currentClimbQueueItem
            ? mirrorItem(state.currentClimbQueueItem)
            : state.currentClimbQueueItem,
      };
    }
  }
}

// MARK: - JS event mapping

export type LegacySyncQueueEvent =
  | {
      __typename: 'FullSync';
      state: { queue: ClimbQueueItem[]; currentClimbQueueItem: ClimbQueueItem | null };
    }
  | { __typename: 'QueueItemAdded'; addedItem?: ClimbQueueItem; item?: ClimbQueueItem; position?: number | null }
  | { __typename: 'QueueItemRemoved'; uuid: string }
  | { __typename: 'QueueReordered'; uuid: string; oldIndex: number; newIndex: number }
  | {
      __typename: 'CurrentClimbChanged';
      currentItem?: ClimbQueueItem | null;
      item?: ClimbQueueItem | null;
      clientId?: string | null;
      correlationId?: string | null;
    }
  | { __typename: 'ClimbMirrored'; mirrored: boolean; mirroredUuid?: string | null };

export type LegacyEventMapping = { kind: 'dispatch'; action: LegacyQueueAction } | { kind: 'ignore'; reason: string };

export function legacyMapQueueEventToAction(
  event: LegacySyncQueueEvent,
  context?: { myClientId?: string | null },
): LegacyEventMapping {
  switch (event.__typename) {
    case 'FullSync':
      return {
        kind: 'dispatch',
        action: {
          type: 'INITIAL_QUEUE_DATA',
          payload: { queue: event.state.queue, currentClimbQueueItem: event.state.currentClimbQueueItem },
        },
      };

    case 'QueueItemAdded': {
      const added = event.addedItem ?? event.item;
      if (!added) return { kind: 'ignore', reason: 'no item payload' };
      return {
        kind: 'dispatch',
        action: { type: 'DELTA_ADD_QUEUE_ITEM', payload: { item: added, position: event.position ?? undefined } },
      };
    }

    case 'QueueItemRemoved':
      return { kind: 'dispatch', action: { type: 'DELTA_REMOVE_QUEUE_ITEM', payload: { uuid: event.uuid } } };

    case 'QueueReordered':
      return {
        kind: 'dispatch',
        action: {
          type: 'DELTA_REORDER_QUEUE_ITEM',
          payload: { uuid: event.uuid, oldIndex: event.oldIndex, newIndex: event.newIndex },
        },
      };

    case 'CurrentClimbChanged': {
      const incoming = event.currentItem !== undefined ? event.currentItem : (event.item ?? null);
      return {
        kind: 'dispatch',
        action: {
          type: 'DELTA_UPDATE_CURRENT_CLIMB',
          payload: {
            item: incoming,
            shouldAddToQueue: incoming != null,
            insertAfterCurrent: true,
            isServerEvent: true,
            eventClientId: event.clientId ?? undefined,
            myClientId: context?.myClientId ?? undefined,
            serverCorrelationId: event.correlationId ?? undefined,
          },
        },
      };
    }

    case 'ClimbMirrored':
      return {
        kind: 'dispatch',
        action: {
          type: 'DELTA_MIRROR_CURRENT_CLIMB',
          payload: { mirrored: event.mirrored, mirroredUuid: event.mirroredUuid ?? null },
        },
      };
  }
}

// MARK: - Swift QueueStateReducer port

/** `SharedQueueItem`, reduced to what the reducer reads. */
export type SwiftQueueItem = {
  uuid: string;
  climbUuid: string;
  mirrored: boolean;
};

export type SwiftQueueEvent =
  | { kind: 'fullSync'; items: SwiftQueueItem[]; currentItem: SwiftQueueItem | null; sequence: number }
  | { kind: 'currentClimbChanged'; item: SwiftQueueItem | null; sequence: number }
  | { kind: 'itemAdded'; item: SwiftQueueItem; position: number; sequence: number }
  | { kind: 'itemRemoved'; uuid: string; sequence: number }
  | { kind: 'reordered'; uuid: string; oldIndex: number; newIndex: number; sequence: number }
  | { kind: 'climbMirrored'; uuid: string | null; mirrored: boolean; sequence: number };

export type SwiftQueueState = {
  items: SwiftQueueItem[];
  currentIndex: number;
};

/** `QueueMessageParser.parseQueueItem`, from a wire queue item. */
export function toSwiftQueueItem(item: ClimbQueueItem): SwiftQueueItem {
  return { uuid: item.uuid, climbUuid: item.climb.uuid, mirrored: item.climb.mirrored ?? false };
}

function swiftCurrentItemUuid(state: SwiftQueueState): string | null {
  if (state.currentIndex < 0 || state.currentIndex >= state.items.length) return null;
  return state.items[state.currentIndex].uuid;
}

function swiftResolveCurrentIndex(previousUuid: string | null, previousIndex: number, items: SwiftQueueItem[]): number {
  if (previousUuid !== null) {
    const index = items.findIndex((item) => item.uuid === previousUuid);
    if (index >= 0) return index;
  }
  return Math.min(Math.max(previousIndex, 0), Math.max(items.length - 1, 0));
}

function swiftStateSettingCurrent(
  item: SwiftQueueItem | null,
  items: SwiftQueueItem[],
  fallbackIndex: number,
): SwiftQueueState {
  if (!item) return { items, currentIndex: fallbackIndex };
  const index = items.findIndex((queued) => queued.uuid === item.uuid);
  if (index >= 0) return { items, currentIndex: index };
  const appended = [...items, item];
  return { items: appended, currentIndex: appended.length - 1 };
}

export function swiftApply(event: SwiftQueueEvent, state: SwiftQueueState): SwiftQueueState {
  const items = [...state.items];
  const currentUuid = swiftCurrentItemUuid(state);

  switch (event.kind) {
    case 'fullSync':
      return swiftStateSettingCurrent(event.currentItem, [...event.items], 0);

    case 'currentClimbChanged':
      if (!event.item) return state;
      return swiftStateSettingCurrent(event.item, items, state.currentIndex);

    case 'itemAdded': {
      const insertIndex = Math.min(Math.max(event.position, 0), items.length);
      items.splice(insertIndex, 0, event.item);
      return { items, currentIndex: swiftResolveCurrentIndex(currentUuid, state.currentIndex, items) };
    }

    case 'itemRemoved': {
      const removeIndex = items.findIndex((item) => item.uuid === event.uuid);
      if (removeIndex === -1) return state;
      items.splice(removeIndex, 1);
      return { items, currentIndex: swiftResolveCurrentIndex(currentUuid, state.currentIndex, items) };
    }

    case 'reordered': {
      let sourceIndex: number;
      if (event.oldIndex >= 0 && event.oldIndex < items.length && items[event.oldIndex].uuid === event.uuid) {
        sourceIndex = event.oldIndex;
      } else {
        sourceIndex = items.findIndex((item) => item.uuid === event.uuid);
        if (sourceIndex === -1) return state;
      }
      const [moved] = items.splice(sourceIndex, 1);
      const destination = Math.min(Math.max(event.newIndex, 0), items.length);
      items.splice(destination, 0, moved);
      return { items, currentIndex: swiftResolveCurrentIndex(currentUuid, state.currentIndex, items) };
    }

    case 'climbMirrored': {
      if (event.uuid === null) return state;
      const itemIndex = items.findIndex((item) => item.uuid === event.uuid);
      if (itemIndex === -1) return state;
      items[itemIndex] = { ...items[itemIndex], mirrored: event.mirrored };
      return { items, currentIndex: state.currentIndex };
    }
  }
}

export type SwiftSequenceDecision = { kind: 'apply'; newLastSequence: number } | { kind: 'resync' };

/** `QueueSequencePolicy.decision` with `QueueMessageParser.hasSequenceGap`. -1 means no sequence yet. */
export function swiftSequenceDecision(event: SwiftQueueEvent, lastKnown: number): SwiftSequenceDecision {
  if (event.kind === 'fullSync') return { kind: 'apply', newLastSequence: event.sequence };
  const hasGap = lastKnown >= 0 && event.sequence > lastKnown + 1;
  if (hasGap) return { kind: 'resync' };
  return { kind: 'apply', newLastSequence: event.sequence };
}

/** `QueueEventRepaintPolicy.shouldRepaintBoard`. */
export function swiftShouldRepaintBoard(event: SwiftQueueEvent): boolean {
  return event.kind === 'currentClimbChanged' || event.kind === 'climbMirrored';
}
